    int max_len = 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", patterns[i]);
        lengths[i] = strlen(patterns[i]);
        if (lengths[i] > max_len) {
            max_len = lengths[i];
        }
    }

    if (max_len > MAX_LEN) {
