    int last_one = -1;
    for (int i = 0; i < max_len; i++) {
        if (result[i] == '1') {
            last_one = i;
        }
    }

    if (last_one == -1) {
        printf("0\n");
    } else {
        result[last_one + 1] = '\0';
        printf("%s\n", result);
