int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char s[2055];
    char ans[2055];
    int initialized = 0;

    for (int i = 0; i < N; i++) {
        if (scanf("%s", s) != 1) return 0;

        if (!initialized) {
            strcpy(ans, s);
            initialized = 1;
            continue;
        }

        char next[2055];
        int p1 = 0, p2 = 0, k = 0;
        int len1 = (int)strlen(ans);
        int len2 = (int)strlen(s);

        while (p1 < len1 || p2 < len2) {
            if (k >= 2049) {
                printf("Too complex.\n");
                return 0;
            }

            char c1 = (p1 < len1) ? ans[p1] : '\0';
            char c2 = (p2 < len2) ? s[p2] : '\0';

            if (c1 == '.' && c2 == '.') {
                next[k++] = '.';
                p1++;
                p2++;
            } else if (c1 == '.') {
                next[k++] = c2;
                p1++;
                p2++;
            } else if (c2 == '.') {
                next[k++] = c1;
                p1++;
                p2++;
            } else if (c1 == '\0') {
                next[k++] = c2;
                p2++;
            } else if (c2 == '\0') {
                next[k++] = c1;
                p1++;
            } else {
                next[k++] = '[';
                next[k++] = c1;
                next[k++] = c2;
                next[k++] = ']';
                p1++;
                p2++;
                if (k > 2048) {
                    printf("Too complex.\n");
                    return 0;
                }
            }
        }

        next[k] = '\0';
        if (k > 2048) {
            printf("Too complex.\n");
            return 0;
        }
        strcpy(ans, next);
    }

    if (!initialized) ans[0] = '\0';

    if ((int)strlen(ans) > 2048) {
        printf("Too complex.\n");
    } else {
        printf("%s\n", ans);
    }

    return 0;
}

