int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    while (cin >> N) {
        vector<string> patterns(N);
        for (int i = 0; i < N; ++i) cin >> patterns[i];

        string result;
        bool firstToken = true;
        bool tooComplex = false;

        for (int i = 0; i < N && !tooComplex; ++i) {
            const string &s = patterns[i];
            int j = 0, m = (int)s.size();

            while (j < m) {
                // Parse one token: optional '/'s, one note letter, optional digit
                int slashCnt = 0;
                while (j < m && s[j] == '/') {
                    ++slashCnt;
                    ++j;
                }

                if (j >= m) break; // safety

                char note = s[j++];
                string token;
                token.append(slashCnt, '/');
                token.push_back(note);

                if (j < m && isdigit((unsigned char)s[j])) {
                    token.push_back(s[j]);
                    ++j;
                }

                if (!firstToken) result.push_back(' ');
                result += token;
                firstToken = false;

                if ((int)result.size() > 2048) {
                    tooComplex = true;
                    break;
                }
            }
        }

        if (tooComplex) cout << "Too complex.\n";
        else cout << result << "\n";
    }

    return 0;
}

