import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;
        int N = Integer.parseInt(first.trim());

        List<String> patterns = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            String s = br.readLine();
            if (s == null) s = "";
            patterns.add(s.trim());
        }

        String result = combine(patterns);
        if (result.length() > 2048) {
            System.out.println("Too complex.");
        } else {
            System.out.println(result);
        }
    }

    static String combine(List<String> patterns) {
        String cur = "";
        for (String p : patterns) {
            cur = merge(cur, p);
            if (cur.length() > 2048) break;
        }
        return cur;
    }

    static String merge(String a, String b) {
        if (a.isEmpty()) return b;
        if (b.isEmpty()) return a;

        int la = expandedLength(a);
        int lb = expandedLength(b);
        int l = lcm(la, lb);

        String ea = expandToLength(a, l);
        String eb = expandToLength(b, l);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < l; i++) {
            char ca = ea.charAt(i);
            char cb = eb.charAt(i);
            if (ca == '.') sb.append(cb);
            else if (cb == '.') sb.append(ca);
            else {
                // both are sounds; advanced machine can play up to 8 simultaneously
                // represent simultaneous sounds by concatenating distinct chars in sorted order
                if (ca == cb) sb.append(ca);
                else {
                    if (ca < cb) {
                        sb.append('{').append(ca).append(cb).append('}');
                    } else {
                        sb.append('{').append(cb).append(ca).append('}');
                    }
                }
            }
        }
        return compress(sb.toString());
    }

    static int expandedLength(String s) {
        int len = 0;
        for (int i = 0; i < s.length(); ) {
            char c = s.charAt(i);
            if (c == '{') {
                int j = s.indexOf('}', i);
                len++;
                i = j + 1;
            } else {
                len++;
                i++;
            }
        }
        return len;
    }

    static String expandToLength(String s, int target) {
        List<String> tokens = tokenize(s);
        int base = tokens.size();
        int repeat = target / base;
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < repeat; r++) {
            for (String t : tokens) sb.append(t);
        }
        return sb.toString();
    }

    static List<String> tokenize(String s) {
        List<String> tokens = new ArrayList<>();
        for (int i = 0; i < s.length(); ) {
            if (s.charAt(i) == '{') {
                int j = s.indexOf('}', i);
                tokens.add(s.substring(i, j + 1));
                i = j + 1;
            } else {
                tokens.add(String.valueOf(s.charAt(i)));
                i++;
            }
        }
        return tokens;
    }

    static String compress(String s) {
        // Simple compression: if the whole string is repetition of a smaller token sequence, reduce it.
        List<String> tokens = tokenize(s);
        int n = tokens.size();
        for (int len = 1; len <= n; len++) {
            if (n % len != 0) continue;
            boolean ok = true;
            for (int i = len; i < n && ok; i++) {
                if (!tokens.get(i).equals(tokens.get(i % len))) ok = false;
            }
            if (ok) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < len; i++) sb.append(tokens.get(i));
                return sb.toString();
            }
        }
        return s;
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static int lcm(int a, int b) {
        return a / gcd(a, b) * b;
    }
}
